"""Fake of `runlog.progress` (sharing `runlog.Progress/`, see `contracts.SHARED_FOLDERS`): the
35% snapshot for any path whose last part is `snake-default-s1`; any other path raises
`FileNotFoundError`, as the real one does when no run is there.
"""

from pathlib import Path

from rllab.runlog import Progress


def build(fx, case: str):
    rec = fx.recording(case)
    snapshot = fx.decode(Progress, rec["progress"])

    def progress(path) -> Progress:
        if Path(path).name != rec["run"]:
            raise FileNotFoundError(f"no run at {path}")
        return snapshot

    return progress
